@js:
// ===== 极速版：直接从列表页提取图片 =====
var doc = org.jsoup.Jsoup.parse(result);
var imgUrls = [];
var baseUrl = 'https://www.wnacg.com';

// 方法1：从列表页直接提取图片链接（最快，无需额外请求）
// 匹配缩略图链接，然后替换为原图
var thumbLinks = doc.select("#bodywrap > div.grid > div > ul > li div.pic_box.tb > a > img");

if (thumbLinks.size() === 0) {
    thumbLinks = doc.select("div.pic_box.tb img, ul.cc li img, .grid li img");
}

if (thumbLinks.size() > 0) {
    // 从缩略图URL推断原图URL
    for (var i = 0; i < thumbLinks.size(); i++) {
        var src = thumbLinks.get(i).attr("src");
        if (src) {
            // 缩略图格式通常是：https://xxx.wnacg.com/data/2024/01/xxxxx.jpg
            // 原图格式相同，只是分辨率不同，直接使用原链接
            if (!src.startsWith("http")) {
                if (src.startsWith("//")) {
                    src = "https:" + src;
                } else {
                    src = baseUrl + src;
                }
            }
            imgUrls.push(src);
        }
    }
}

// 方法2：如果方法1没获取到，尝试从详情页获取（备用方案，仅当方法1失败时使用）
if (imgUrls.length === 0) {
    var links = doc.select("#bodywrap > div.grid > div > ul > li div.pic_box.tb > a");
    if (links.size() === 0) {
        links = doc.select("#bodywrap div.grid li a, div.cc li a, div.grid li a");
    }

    // 只取前3张作为示例（防止卡顿）
    var maxSample = Math.min(links.size(), 3);
    for (var j = 0; j < maxSample; j++) {
        var href = links.get(j).attr("href");
        if (href) {
            if (!href.startsWith("http")) {
                href = baseUrl + href;
            }
            try {
                var pageHtml = java.ajax(href);
                var pageDoc = org.jsoup.Jsoup.parse(pageHtml);
                var picarea = pageDoc.select("#picarea").first();
                if (picarea != null) {
                    var realSrc = picarea.attr("src");
                    if (realSrc) {
                        if (!realSrc.startsWith("http")) {
                            realSrc = "https:" + (realSrc.startsWith("//") ? realSrc : "//" + realSrc);
                        }
                        // 推断所有图片的URL模式
                        // 从realSrc中提取基础路径和命名模式
                        var lastSlash = realSrc.lastIndexOf('/');
                        if (lastSlash > 0) {
                            var basePath = realSrc.substring(0, lastSlash + 1);
                            var fileName = realSrc.substring(lastSlash + 1);
                            // 尝试解析页码
                            var numMatch = fileName.match(/^(\d+)/);
                            if (numMatch) {
                                var startNum = parseInt(numMatch[1]);
                                var ext = fileName.substring(fileName.lastIndexOf('.'));
                                // 生成所有图片URL（根据列表页图片数量）
                                for (var k = 0; k < links.size(); k++) {
                                    var padded = String(startNum + k).padStart(fileName.length - ext.length, '0');
                                    imgUrls.push(basePath + padded + ext);
                                }
                                break;
                            }
                        }
                        imgUrls = []; // 如果推断失败，清空
                        break;
                    }
                }
            } catch(e) {
                java.log("备用方案失败: " + e);
            }
        }
    }
}

// 方法3：兜底 - 从旧版格式提取
if (imgUrls.length === 0) {
    var names = doc.select("div.title span.name");
    if (names.size() > 0) {
        var timeMatch = doc.text().match(/(\d{4})-(\d{2})/);
        var year = timeMatch ? timeMatch[1] : '2020';
        var month = timeMatch ? timeMatch[2] : '01';
        var path = '/' + year + '/' + month + '/';
        var checkId = 't3';

        for (var m = 0; m < names.size(); m++) {
            var fname = names.get(m).text().trim();
            if (fname) {
                imgUrls.push('https://' + checkId + '.wnacg.com/data' + path + fname + '.jpg');
            }
        }
    }
}

// 生成最终HTML
if (imgUrls.length === 0) {
    result = '<p style="text-align:center;padding:20px;color:#999;">⚠️ 无法获取图片，请尝试切换其他页面</p>';
} else {
    var imgHtml = '';
    for (var n = 0; n < imgUrls.length; n++) {
        // 使用loading=lazy延迟加载，减少内存占用
        imgHtml += '<img src="' + imgUrls[n] + '" style="max-width:100%;display:block;margin:0 auto;" loading="lazy" decoding="async">';
    }
    // 添加图片总数信息
    var info = '<div style="text-align:center;padding:10px 0;color:#666;font-size:13px;">📖 共 ' + imgUrls.length + ' 张图片</div>';
    result = info + imgHtml;
}
